    nemadc_MIPI_out(hwdev,0x18);
    nemadc_MIPI_out(hwdev,0x1a);
    nemadc_MIPI_out(hwdev,0xf);
    nemadc_MIPI_out(hwdev,MIPI_DBIB_CMD | 0xf1);
    nemadc_MIPI_out(hwdev,0x2);
    nemadc_MIPI_out(hwdev,0x27);
    nemadc_MIPI_out(hwdev,0x1b);
    nemadc_MIPI_out(hwdev,0x37);
    nemadc_MIPI_out(hwdev,0x59);
    nemadc_MIPI_out(hwdev,0x03);
    nemadc_MIPI_out(hwdev,0x30);
    nemadc_MIPI_out(hwdev,0x0);
    nemadc_MIPI_out(hwdev,0x0);
    nemadc_MIPI_out(hwdev,0x1f);
    nemadc_MIPI_out(hwdev,0xf);
    nemadc_MIPI_out(hwdev,0x17);
    nemadc_MIPI_out(hwdev,0x1a);
    nemadc_MIPI_out(hwdev,0xf);
    nemadc_MIPI_out(hwdev,MIPI_DBIB_CMD | 0xfe);
    nemadc_MIPI_out(hwdev,MIPI_DBIB_CMD | 0xff);
    nemadc_MIPI_out(hwdev,MIPI_DBIB_CMD | 0x35);
    nemadc_MIPI_out(hwdev,0x0);
    nemadc_MIPI_out(hwdev,MIPI_DBIB_CMD | 0x44);
    nemadc_MIPI_out(hwdev,0x0);
    nemadc_MIPI_out(hwdev,MIPI_DBIB_CMD | 0x11); /* wait for power stability */
    mdelay(1);
    // nemadc_MIPI_out(hwdev,MIPI_DBIB_CMD | MIPI_set_display_on);
