    nemadc_MIPI_out(hwdev,0);
    nemadc_MIPI_out(hwdev,0+2);
    nemadc_MIPI_out(hwdev,0);
    nemadc_MIPI_out(hwdev,127+2);
    nemadc_MIPI_out(hwdev,MIPI_DBIB_CMD  | 0x2b); // x
    nemadc_MIPI_out(hwdev,0);
    nemadc_MIPI_out(hwdev,0+3);
    nemadc_MIPI_out(hwdev,0);
    nemadc_MIPI_out(hwdev,127+3);
    // nemadc_MIPI_out(hwdev,MIPI_DBIB_CMD  | 0x2c);
    // nemadc_MIPI_out(hwdev,MIPI_DBIB_CMD | MIPI_set_display_off);
#endif
    // nemadc_MIPI_set_position(hwdev,0,0,0,160);
